namespace {
struct TermFixture:RoundFixture {
 PoliticalTermHandoverCatalog term_catalog;PoliticalTermHandoverState terms;FamilyDeathOriginRead term_death;
 // 新专项Grant只授本任让职，不借上一轮提名或让职权限。
 TermFixture(){auto* office=catalog.offices.find("chief");office->grant_ids.push_back("term.handover");state.offices.find("chief")->grant_ids.push_back("term.handover");Grant g;g.id="term.handover";g.office_id="chief";g.allowed_command_kinds={political_term_handover_offer_command,political_term_handover_withdraw_command};g.scopes={{ScopeRef::Kind::site,"hall"}};catalog.grants.insert(g.id,g);term_catalog.policies.insert("later",{"later","next",g.id,4});}
 // 纯来源桥只映射真实原Office原因，不递归完整新账。
 PoliticalHeadSourceContext term_heads(){auto h=heads();h.term_handover_head=[this](const auto& p,const auto& office){return read_political_term_handover_head_source(common,term_catalog,terms,round_catalog,p,office);};return h;}
 PoliticalTermHandoverContext term_context(const PoliticalHeadSourceContext& h){return {common,*cc,state,catalog,economy,activity,h,round_catalog,rounds,term_catalog,terms,term_death,[](const PoliticalSuccessionPolicy&,Integer,const StableId&){return common_success();},[this](Integer,const StableId& fact)->Outcome<StableId>{auto i=historical_players.find(fact);return i==historical_players.end()?Outcome<StableId>{false,{},common_failure("FixturePlayerSourceMissing").error}:Outcome<StableId>{true,i->second,{}};}};}
 PoliticalOfferTermHandover offer_later(){return {{"city","chief",1,"candidate"},"later","leader",installed,1};}
 Outcome<PoliticalTermHandoverQuote> preview_term(const StableId& actor,const PoliticalTermHandoverCommand& command){auto h=term_heads();return preview_political_term_handover(term_context(h),actor,command);}
 Status validate_terms(){auto h=term_heads();return validate_political_term_handover_sources(term_context(h));}
 // 实际Common请求/结果先入缓存和history，再绑定唯一新源；没有伪造预先成功收据。
 StableId commit_term(const StableId& actor,const PoliticalTermHandoverCommand& command){common.state().metadata.player_actor_id=actor;auto before=terms;auto h=term_heads();auto x=term_context(h);auto q=take(preview_political_term_handover(x,actor,command));auto id=take(apply_political_term_handover_in_candidate(common,state,terms,x,actor,command,q));historical_players[id]=actor;auto kind=political_term_handover_command_kind(command);check(take(political_term_handover_new_player_source(before,terms,actor,kind,common.tick()))==id,"exact new later-term source");auto result=std::make_shared<CommitResult>();result->ok=true;result->kind=kind;result->tick=common.tick();result->revision=++common.state().identity.revision;result->result_id=take(common.next_id("result"));const auto* previous=common.state().request_sequences.find(actor);Integer request=previous?*previous+1:1;common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),result);common.state().history.push_back({result->tick,kind,actor,result->result_id,{}});take(bind_political_term_handover_player_result(common,terms,id,actor,request,*result,[&](const auto&,const auto& source,const auto& changed){const auto* answer=terms.answers.find(id);return source==id&&changed==(answer?answer->office_change_fact_id:StableId{});}));check(validate_terms().ok,"true later-term sources validate");return id;}
};
}
