int main(){try{
 TermFixture f;auto original=f.offer_later();original.authority={"city","chief",0,"leader"};original.candidate_actor_id="candidate";original.expected_office_epoch=0;check(!f.preview_term("leader",original).ok,"authored head still uses first-head制度");f.install();auto offered=f.commit_term("candidate",f.offer_later());check(f.terms.offers.find(offered)->head_source_fact_id==f.installed&&f.state.offices.find("chief")->epoch==1,"offer freezes actual installed term without moving Office");auto accepted=f.commit_term("leader",PoliticalAnswerTermHandover{offered,true,1});check(f.state.offices.find("chief")->holder_actor_id==std::optional<StableId>{"leader"}&&f.state.offices.find("chief")->epoch==2,"original Office changes once at real personal acceptance");
 auto h=f.term_heads();auto root=take(read_political_successor_round_head(h,f.round_catalog,f.rounds,"next"));check(root&&root->origin==PoliticalHeadOrigin::term_handover&&root->source_fact_id==accepted,"new later living term is explicit next death-nomination root");auto no_bridge=f.heads();check(!read_political_successor_round_head(no_bridge,f.round_catalog,f.rounds,"next").ok,"absent explicit later-term reader cannot guess current holder source");
 PoliticalOfferTermHandover again{{"city","chief",2,"leader"},"later","candidate",accepted,2};auto second=f.commit_term("leader",again);f.commit_term("candidate",PoliticalAnswerTermHandover{second,false,2});check(f.state.offices.find("chief")->epoch==2&&!f.preview_term("candidate",PoliticalAnswerTermHandover{second,true,2}).ok,"decline permanently closes exactly this offer without Office write");
 auto changed=f.terms.offers.find(offered)->head_source_fact_id;f.terms.offers.find(offered)->head_source_fact_id=accepted;check(!f.validate_terms().ok,"later same-tick source cannot backfill original offer root");f.terms.offers.find(offered)->head_source_fact_id=changed;
 auto raw=encode_political_term_handover_state(f.terms);check(compare_boundary(raw,encode_political_term_handover_state(take(decode_political_term_handover_state(raw)))).exact(),"new independent state preserves all exact roots and permanent results");
 TermFixture revoked;revoked.install();auto pending=revoked.commit_term("candidate",revoked.offer_later());revoked.catalog.grants.find("term.handover")->valid_until=0;revoked.common.state().identity.tick=1;revoked.common.state().metadata.player_actor_id="leader";check(!revoked.preview_term("leader",PoliticalAnswerTermHandover{pending,true,1}).ok,"actual acceptance rechecks original incumbent dedicated Grant expiry");
 TermFixture stale;stale.install();auto old=stale.commit_term("candidate",stale.offer_later());stale.change("leader");stale.common.state().metadata.player_actor_id="leader";check(!stale.preview_term("leader",PoliticalAnswerTermHandover{old,true,1}).ok,"new incumbent or epoch cannot reuse earlier willingness");
 std::cout<<checks<<" later-term source assertions; not executed as World\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
#endif
